    lines: tuple[SlipLine, ...]


@dataclass(frozen=True)
class StockLevel:
    product: Product
    on_hand: int


class FulfilmentService:
    def __init__(self, orders: InMemoryOrderRepository, customers: InMemoryCustomerRepository,
                 catalog: InMemoryProductCatalog, stock: InMemoryStockRepository) -> None:
        self._orders = orders
        self._customers = customers
        self._catalog = catalog
        self._stock = stock

    def low_stock(self, threshold: int) -> list[StockLevel]:
        """Active products with on-hand stock strictly below ``threshold``, lowest first, then by SKU."""
        levels = [StockLevel(p, self._stock.get(p.sku)) for p in self._catalog.list_all() if p.active]
        levels = [level for level in levels if level.on_hand < threshold]
        return sorted(levels, key=lambda level: (level.on_hand, level.product.sku))

