def test_restock_rejects_invalid_requests_without_change(shop):
    bad_requests = [
        {"sku": "", "quantity": 1},
        {"sku": 7, "quantity": 1},
        {"quantity": 1},
        {"sku": "LAMP", "quantity": 0},
        {"sku": "LAMP", "quantity": -2},
